class Solution {
public:
    long long maxScore(vector<int>& nums) {
        vector<int> stk;
        for (int i = 0; i < nums.size(); ++i) {
            while (!stk.empty() && nums[stk.back()] <= nums[i]) {
                stk.pop_back();
            }
            stk.push_back(i);
        }
        long long ans = 0;
        int curr_idx = 0;
        for (int j : stk) {
            ans += 1LL * (j - curr_idx) * nums[j];
            curr_idx = j;
        }
        return ans;
    }
};

class Solution {
    public long maxScore(int[] nums) {
        Deque<Integer> stk = new ArrayDeque<>();
        for (int i = 0; i < nums.length; ++i) {
            while (!stk.isEmpty() && nums[stk.peek()] <= nums[i]) {
                stk.pop();
            }
            stk.push(i);
        }
        long ans = 0;
        int currIdx = 0;
        List<Integer> indices = new ArrayList<>(stk);
        Collections.reverse(indices);
        for (int j : indices) {
            ans += (long) (j - currIdx) * nums[j];
            currIdx = j;
        }
        return ans;
    }
}

var maxScore = function(nums) {
